input.command:
cd <RUN>/project; python3 - <<'EOF'
import json
p='.agent-workflow/features/FEAT-001/verification.json'
d=json.load(open(p))
cov={
 'requirement:R-1:1:ae0e453b6e4d':"parser-all exact-equality assertions cover each CSV source rule: optional BOM + quoted comma/multiline (test_upper.test_quoted_multiline_bom), empty input (test_upper.test_empty, test_integration), header mismatch single line-1 error and stop (test_upper.test_header, test_contract.test_csv_header_trim_and_stop), header/field trim (test_contract header trim, test_upper.test_missing_extra_and_trim), logical row numbering after multiline (test_contract.test_csv_logical_lines_after_multiline), missing sku/name and missing/extra fields as invalid_row with exact lines (test_contract.test_csv_row_errors_exact_and_atomic), finite Decimal >=0 with <=2 fractional digits incl. NaN/sNaN/+-Infinity/-1/0.001/0.000/oops without exceptions and exact 2-dp formatting incl. -0 (test_upper.test_invalid_prices/test_prices, test_contract.test_csv_finite_decimal_formats), first-SKU acceptance with invalid rows not reserving and duplicate_sku lines (test_upper/test_contract duplicate tests), record/error order and exact {sku,name,price}/{line,code} shapes via whole-dict equality.",
 'requirement:R-1:2:268e8b047d1a':"parser-all exact-equality assertions cover each JSONL source rule: blank lines ignored with physical one-based line numbers (test_lower.test_bad_json_and_line_numbers, test_contract.test_json_payload_types_and_physical_order), empty input (test_lower.test_empty, test_integration), invalid_json, non-object and each missing/wrong-type/empty id/timestamp/missing payload as invalid_event (test_contract.test_json_schema_fields_individually, test_lower.test_invalid_schema), payload any JSON value (null/0/text/[]/{}/true), naive/unparseable/impossible-date/out-of-range-offset timestamps as invalid_timestamp and Z/+/- offsets normalized to UTC YYYY-MM-DDTHH:MM:SSZ (test_lower.test_offsets/test_bad_timestamps, test_contract.test_json_z_negative_offsets_and_calendar), first valid id accepted with invalid events not reserving and duplicate_id (test_lower.test_duplicate_and_invalid_does_not_reserve), order and exact {id,timestamp,payload}/{line,code} shapes (test_lower.test_offsets/test_order)."}
for it in d['items']:
    if it['id'] in cov:
        it['mode']='automatic'; it['gates']=['parser-all']; it['coverage']=cov[it['id']]
json.dump(d,open(p,'w'),indent=2); open(p,'a').write('\n')
EOF
S=../plugin/skills/dev/core/scripts; python3 $S/verification.py run . FEAT-001; echo EXIT=$?
